// Generated by DeepSeek
$(document).ready(() => {
  const employerLinks = $(".employer-link");
  const titleLinks = $(".title-link");

  employerLinks.each((index, element) => {
    const strongElement = $(element).children("strong");
    let employerName = strongElement.text().trim();
    employerName = employerName.replaceAll(" ", "+");

    const newUrl = `${window.origin}/contacts/?given_name=&surname=&employment_history=${employerName}&job_titles=`;
    $(element).attr("href", newUrl);
  });

  titleLinks.each((index, element) => {
    let title = $(element).text().trim();
    title = title.replaceAll(" ", "+");

    const newUrl = `${window.origin}/contacts/?given_name=&surname=&employment_history=&job_titles=${title}`;
    $(element).attr("href", newUrl);
  });
});
